package com.wizzadrds.theworldremembers.dream; import com.wizzadrds.theworldremembers.memory.*; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*; class DreamSelectorTest {@Test void memorySelectionIsGrounded(){UUID n=UUID.randomUUID(),p=UUID.randomUUID();var m=new Memory(n,p,MemoryEventType.NPC_MARRIED,10,MemoryImportance.IMPORTANT);assertTrue(DreamSelector.selectMemory(n,List.of(m),20).isPresent());} @Test void fearRequiresHighStress(){UUID n=UUID.randomUUID(),p=UUID.randomUUID();var m=new Memory(n,p,MemoryEventType.NPC_DIED,10,MemoryImportance.IMPORTANT);assertTrue(DreamSelector.selectFear(n,List.of(m),20,80).isPresent());assertTrue(DreamSelector.selectFear(n,List.of(m),20,20).isEmpty());}}
